<?php
use App\Repositories\Connection;use App\Services\LoginService;use App\Services\ManagerAvailabilityService;use App\Utils\LocationUtils;use App\Utils\MessageUtil;use App\Utils\Router;use App\Utils\TemplateResponse;use App\Utils\UserContext;
$router=new Router();
$router->get(function(){$user=LoginService::getSession();$db=new Connection();$db->query("SELECT * FROM manager_availability WHERE id_owner=:owner AND manager_id=:manager AND ends_at>=CURDATE() ORDER BY starts_at");$db->bind(':owner',$user->getOwner());$db->bind(':manager',$user->getId());return TemplateResponse::render(__DIR__.'/index.twig',[...UserContext::get(),'blocks'=>$db->fetchAll(),'today'=>date('Y-m-d'),'horizon'=>date('Y-m-d',strtotime('+6 months'))]);});
$router->post(function(){$user=LoginService::getSession();$start=(string)($_POST['start_date']??'');$end=(string)($_POST['end_date']??$start);$today=date('Y-m-d');$horizon=date('Y-m-d',strtotime('+6 months'));if(!$start||$start<$today||$end<$start||$end>$horizon){MessageUtil::setMessage('Choose dates between today and six months from today.','Invalid availability window','warning');LocationUtils::redirectInternal('panel/manager-availability');}$db=new Connection();if(($_POST['action']??'save')==='delete'){$db->query("DELETE FROM manager_availability WHERE id=:id AND id_owner=:owner AND manager_id=:manager");$db->bind(':id',(int)$_POST['id']);$db->bind(':owner',$user->getOwner());$db->bind(':manager',$user->getId());$db->execute();}else{$db->query("INSERT INTO manager_availability(id_owner,manager_id,starts_at,ends_at,availability,note,created_by) VALUES(:owner,:manager,:start,:end,:availability,:note,:manager)");$db->bind(':owner',$user->getOwner());$db->bind(':manager',$user->getId());$db->bind(':start',$start.' 00:00:00');$db->bind(':end',date('Y-m-d H:i:s',strtotime($end.' +1 day')));$db->bind(':availability',($_POST['availability']??'UNAVAILABLE')==='AVAILABLE'?'AVAILABLE':'UNAVAILABLE');$db->bind(':note',trim((string)($_POST['note']??''))?:null);$db->execute();if(($_POST['availability']??'')==='UNAVAILABLE'){$db->query("UPDATE orders SET availability_status='NEEDS_RECHECK',availability_checked_at=NULL WHERE id_owner=:owner AND main_manager_id=:manager AND is_archived=0 AND event_date BETWEEN :start AND :end");$db->bind(':owner',$user->getOwner());$db->bind(':manager',$user->getId());$db->bind(':start',$start);$db->bind(':end',$end);$db->execute();$affected=$db->rowCount();$engine=new ManagerAvailabilityService();$engine->notifyLevelOne($user->getOwner(),trim($user->getName().' '.$user->getLastname()).' marked '.$start.' through '.$end.' unavailable; '.$affected.' assigned event(s) need review.','panel/manager-scheduling');}}MessageUtil::setMessage('Availability updated.');LocationUtils::redirectInternal('panel/manager-availability');});$router->run();
